tool_input.command:
sleep 3
SP=/private/tmp/claude-501/-Users-dev-peekle/ee309bdf-bd7f-4b73-a4e9-b078a07f21ee/scratchpad
cat > "$SP/drive3.exp" <<'EOF'
#!/usr/bin/expect -f
# Waits for the TUI to be genuinely ready before typing. The earlier attempt
# sent the prompt while Claude Code was still swapping screen buffers, so the
# keystrokes went nowhere.
set timeout 90
set dir [lindex $argv 0]
cd $dir
log_user 0
spawn claude --permission-mode manual

# Onboarding dialogs, if this directory has not been trusted yet.
expect {
  -re "trust this folder" { send -- "\r"; exp_continue }
  -re "fullscreen renderer" { send -- "2"; sleep 1; send -- "\r"; exp_continue }
  -re "for shortcuts" { }
  timeout { puts ">>> never reached the prompt"; exit 1 }
}

# The status line appears before the input is wired up.
sleep 6
puts ">>> TUI ready, typing"

foreach ch [split "read note.txt with the Bash tool: cat note.txt" ""] {
  send -- $ch
  sleep 0.03
}
sleep 2
send -- "\r"
puts ">>> prompt sent"

set timeout 120
expect {
  -re "(?i)do you want|No, and tell Claude|1\\. Yes" {
    puts ">>> PERMISSION PROMPT SEEN"
    sleep 3
    send -- "\033"
    sleep 3
  }
  timeout { puts ">>> no permission prompt within timeout" }
}
sleep 2
send -- "\003"
sleep 1
send -- "\003"
sleep 2
EOF
expect "$SP/drive3.exp" "$SP/probe2" 2>&1 | tail -8; echo "=== fixtures ==="; ls fixtures/hooks/ | tr '\n' ' '
